/**
 * Retry utilities
 */

export interface RetryOptions {
	maxAttempts: number
	baseDelayMs: number
	maxDelayMs: number
}

/**
 * Calls `fn` up to `maxAttempts` times, retrying on failure with exponential
 * backoff. Each retry waits `baseDelayMs * 2^attempt` ms (capped at
 * `maxDelayMs`) before trying again. Throws the last error if all attempts fail.
 */
export async function withRetry<T>(fn: () => Promise<T>, options: RetryOptions): Promise<T> {
	const { maxAttempts, baseDelayMs, maxDelayMs } = options

	let lastError: unknown

	for (let attempt = 0; attempt < maxAttempts; attempt++) {
		try {
			return await fn()
		} catch (e) {
			lastError = e
			if (attempt === maxAttempts - 1) {
				break
			}
			const delayMs = Math.min(baseDelayMs * Math.pow(2, attempt), maxDelayMs)
			await new Promise((resolve) => setTimeout(resolve, delayMs))
		}
	}

	throw lastError
}
